export const ALL_1000_FEATURES: FeatureItem[] = RAW_FEATURES.map(([id, title, category, description]) => {
  const catIdx = FEATURE_CATEGORIES.findIndex((c) => c.id === category);
  return {
    id,
    title,
    category,
    description,
    categoryIndex: catIdx >= 0 ? catIdx : 0,
  };
});
